#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    char *name;
    int score;
    struct Node *next;
} Node;

Node *add_last(Node *head, char *name, int score) {
    Node *fresh = malloc(sizeof(Node));
    if (fresh == NULL) {
        return head;
    }
    fresh->name = name;
    fresh->score = score;
    fresh->next = NULL;
    if (head == NULL) {
        return fresh;
    }
    Node *p = head;
    while (p->next != NULL) {
        p = p->next;
    }
    p->next = fresh;
    return head;
}

Node *best_in_list(Node *head) {
    if (head == NULL) {
        return NULL;
    }
    Node *best = head;
    for (Node *p = head->next; p != NULL; p = p->next) {
        if (p->score > best->score) {
            best = p;
        }
    }
    return best;
}

int main(void) {
    Node *head = NULL;
    head = add_last(head, "{n1}", {s1});
    head = add_last(head, "{n2}", {s2});
    head = add_last(head, "{n3}", {s3});

    Node *top = best_in_list(head);
    if (top != NULL) {
        printf("第一名：%s %d 分\n", top->name, top->score);
    } else {
        printf("一个人都没有喵\n");
    }

    Node *nobody = NULL;
    top = best_in_list(nobody);
    if (top != NULL) {
        printf("第一名：%s %d 分\n", top->name, top->score);
    } else {
        printf("一个人都没有喵\n");
    }
    return 0;
}
